const out = [];
for (const item of $input.all()) {
  const link = item.json.link || '';
  const title = item.json.title || '';
  const snippet = item.json.snippet || '';
  if (!link) continue;
  let host = '';
  try { host = new URL(link).hostname; } catch (e) { continue; }
  const isEdu = /\.edu\.cn$/i.test(host) || /\.ac\.cn$/i.test(host);
  if (!isEdu) continue;
  out.push({ json: { university_domain: host, url: link, title, snippet } });
}
return out;

const out = [];
for (const item of $input.all()) {
  let raw = item.json.output || item.json.text || '{}';
  raw = String(raw).replace(/```json|```/g, '').trim();
  let obj; try { obj = JSON.parse(raw); } catch (e) { continue; }
  if (obj.scholarship_available === false) continue;
  const urls = Array.isArray(obj.faculty_urls) ? obj.faculty_urls : [];
  for (const u of urls.slice(0, 3)) {
    if (!u || !/^https?:/i.test(u)) continue;
    out.push({ json: {
      university_name: obj.university_name || '',
      domain: obj.domain || '',
      scholarship_types: obj.scholarship_types || '',
      scholarship_url: obj.scholarship_url || '',
      matched_fields: Array.isArray(obj.matched_fields) ? obj.matched_fields.join(', ') : (obj.matched_fields || ''),
      faculty_url: u
    } });
  }
}
return out;

return $input.all().map(i => {
  const html = String(i.json.data || '');
  const text = html.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0, 12000);
  const emails = [...new Set((html.match(/[A-Za-z0-9._%+-]+(?:@|\(at\)|\[at\])[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || []))].slice(0, 60);
  return { json: { ...i.json, page_text: text, raw_emails: emails } };
});

