const out = [];
for (const item of $input.all()) {
  let raw = item.json.output || item.json.text || '[]';
  raw = String(raw).replace(/```json|```/g, '').trim();
  let arr; try { arr = JSON.parse(raw); } catch (e) { continue; }
  if (!Array.isArray(arr)) continue;
  for (const p of arr) {
    if (!p.email || !/@/.test(p.email)) continue;
    out.push({ json: p });
  }
}
return out;

const rows = ($input.first().json.data || []);
const esc = v => String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const tds = rows.map(r => '<tr>'
  + '<td>' + esc(r.university) + '</td>'
  + '<td>' + esc(r.scholarship) + '</td>'
  + '<td>' + esc(r.matched_field || r.department) + '</td>'
  + '<td>' + esc(r.professor_name) + '</td>'
  + '<td>' + esc(r.title) + '</td>'
  + '<td>' + esc(r.research_area) + '</td>'
  + '<td>' + esc(r.email) + '</td>'
  + '<td>' + (r.profile_url ? '<a href="' + esc(r.profile_url) + '">Link</a>' : '') + '</td>'
  + '</tr>').join('');
const html = '<h2>China Scholarship Universities - MS Biotechnology Professor Contacts</h2>'
  + '<p>Total contacts: ' + rows.length + '</p>'
  + '<table border="1" cellpadding="6" cellspacing="0">'
  + '<tr><th>University</th><th>Scholarship</th><th>Field</th><th>Professor</th><th>Title</th><th>Research Area</th><th>Email</th><th>Profile</th></tr>'
  + tds + '</table>';
const head = ['University','Scholarship','Field','Professor','Title','Research Area','Email','Profile'];
const q = v => '"' + String(v == null ? '' : v).replace(/"/g,'""') + '"';
const csv = head.join(',') + '\n' + rows.map(r => [r.university, r.scholarship, r.matched_field || r.department, r.professor_name, r.title, r.research_area, r.email, r.profile_url].map(q).join(',')).join('\n');
return [{ json: { html, csv, count: rows.length } }];
